  const days = (await db.query("SELECT day::text, active_seconds, sessions FROM device_days WHERE device_id = $1 ORDER BY day DESC LIMIT 60", [id])).rows;
  const flags = (await db.query("SELECT ts, props FROM raw_events WHERE device_id = $1 AND name = 'content_flagged' ORDER BY ts DESC LIMIT 50", [id])).rows;
