  const add = (v) => {
    p.push(v);
    return `$${p.length}`;
  };
  c.push(`${a}.first_seen >= ${add(f.from)}::date`, `${a}.first_seen < ${add(f.to)}::date + 1`);
  if (f.country) c.push(`${a}.country = ${add(f.country)}`);
  if (f.device_type) c.push(`${a}.device_type = ${add(f.device_type)}`);
